<script setup lang="ts">
import {computed, onMounted, ref} from 'vue';

type Row = Record<string, any>;
type Field = {key:string; label:string; type?:string; optional?:boolean; choices?:[string,string][]};
type Screen = {title:string; caption:string; fields:Field[]; columns:[string,string][]};
const token=ref(sessionStorage.getItem('permission-token')||'');
const me=ref<Row|null>(null), page=ref('users'), rows=ref<Row[]>([]), total=ref(0), currentPage=ref(0);
const busy=ref(false), notice=ref(''), failure=ref(false), username=ref(''), password=ref('');
const dialog=ref<HTMLDialogElement|null>(null), editing=ref<Row|null>(null), form=ref<Row>({});
const systems=ref<Row[]>([]), roles=ref<Row[]>([]), permissions=ref<Row[]>([]), resources=ref<Row[]>([]), departments=ref<Row[]>([]), users=ref<Row[]>([]);
const userId=ref(''), roleId=ref(''), permissionId=ref(''), resourceId=ref(''), grantRows=ref<Row[]>([]);
const myPermissions=ref<Row[]>([]), myMenu=ref<Row[]>([]), demo=ref<Row[]>([]);
const currentPassword=ref(''), newPassword=ref('');
const personChoices:[string,string][]=[['EMPLOYEE','正式员工'],['EXTERNAL','外部人员'],['TEMPORARY','临时人员']];
const screens:Record<string,Screen>={
 users:{title:'用户管理',caption:'人员共用同一账号模型，外部与临时身份通过属性和有效期区分。',fields:[{key:'username',label:'登录名'},{key:'displayName',label:'姓名'},{key:'password',label:'初始密码',type:'password'},{key:'departmentId',label:'所属部门',type:'department',optional:true},{key:'personType',label:'人员身份',choices:personChoices},{key:'expiresOn',label:'有效期至',type:'date',optional:true}],columns:[['id','编号'],['username','登录名'],['displayName','姓名'],['personType','人员身份'],['departmentId','部门'],['enabled','状态']]},
 departments:{title:'部门管理',caption:'部门可以包含子部门，存在员工或子部门时不能删除。',fields:[{key:'name',label:'部门名称'},{key:'parentId',label:'上级部门',type:'department',optional:true}],columns:[['id','编号'],['name','名称'],['parentId','上级部门']]},
 systems:{title:'应用管理',caption:'统一维护各应用的权限目录。应用停用会影响其下所有权限和接口。',fields:[{key:'code',label:'应用编码'},{key:'name',label:'应用名称'},{key:'baseUrl',label:'应用地址',optional:true}],columns:[['id','编号'],['code','编码'],['name','名称'],['baseUrl','地址'],['enabled','状态']]},
 roles:{title:'角色管理',caption:'用户通过角色获取权限。多个角色取有效授权的并集。',fields:[{key:'code',label:'角色编码'},{key:'name',label:'角色名称'},{key:'description',label:'说明',optional:true}],columns:[['id','编号'],['code','编码'],['name','名称'],['description','说明'],['enabled','状态']]},
 permissions:{title:'菜单与按钮',caption:'这里只维护前端权限。按钮须属于同一应用的菜单，后端接口在 API 资源中维护。',fields:[{key:'systemId',label:'所属应用',type:'system'},{key:'code',label:'权限编码'},{key:'name',label:'显示名称'},{key:'type',label:'权限类型',choices:[['MENU','菜单'],['BUTTON','按钮']]},{key:'menuPath',label:'菜单地址',optional:true},{key:'parentId',label:'父菜单',type:'menu',optional:true}],columns:[['id','编号'],['code','编码'],['name','名称'],['type','类型'],['parentId','父菜单'],['active','状态']]},
 resources:{title:'API 资源',caption:'以所属应用、HTTP 方法和路径标识接口。接口与前端权限通过独立关系绑定。',fields:[{key:'systemId',label:'所属应用',type:'system'},{key:'name',label:'资源名称'},{key:'method',label:'HTTP 方法',choices:['GET','POST','PUT','PATCH','DELETE'].map(v=>[v,v] as [string,string])},{key:'path',label:'接口路径'}],columns:[['id','编号'],['name','名称'],['method','方法'],['path','路径'],['systemId','应用'],['active','状态']]}
};
const screen=computed(()=>screens[page.value]);
const editableFields=computed(()=>screen.value?.fields.filter(f=>!editing.value||!['username','password','code','systemId'].includes(f.key)).filter(f=>!(editing.value&&page.value==='resources'&&['method','path'].includes(f.key)))||[]);
const adminPages=['users','departments','systems','roles','permissions','resources','grants'];
function message(text:string,error=false){notice.value=text;failure.value=error;}
function logout(){token.value='';sessionStorage.removeItem('permission-token');me.value=null;password.value='';form.value={};demo.value=[];}
async function request(path:string,method='GET',body?:unknown){
 const response=await fetch(path,{method,headers:{'Content-Type':'application/json',...(token.value?{Authorization:`Bearer ${token.value}`}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});
 const data=response.status===204?null:await response.json().catch(()=>null);
 if(!response.ok){if(response.status===401&&path!=='/api/auth/login')logout();throw new Error(data?.message||`请求失败（${response.status}）`);}
 return data;
}
async function run(work:()=>Promise<void>){busy.value=true;try{await work();}catch(e){message(e instanceof Error?e.message:String(e),true);}finally{busy.value=false;}}
async function login(){await run(async()=>{const result=await request('/api/auth/login','POST',{username:username.value,password:password.value});token.value=result.accessToken;sessionStorage.setItem('permission-token',token.value);password.value='';await initialize();message('登录成功');});}
async function initialize(){me.value=await request('/api/me');page.value=me.value?.administrator?'users':'mine';await refresh();}
async function catalogs(){if(!me.value?.administrator)return;[systems.value,roles.value,permissions.value,resources.value,departments.value]=await Promise.all(['/api/systems','/api/roles','/api/permissions','/api/resources','/api/departments'].map(p=>request(p)));users.value=(await request('/api/users?size=100')).items;}
async function refresh(){
 if(screen.value){const result=await request(`/api/${page.value}${page.value==='users'?`?page=${currentPage.value}&size=25`:''}`);rows.value=Array.isArray(result)?result:result.items;total.value=Array.isArray(result)?result.length:result.total;await catalogs();}
 else if(page.value==='grants'){await catalogs();grantRows.value=[];}
 else if(page.value==='mine'){[myPermissions.value,myMenu.value]=await Promise.all([request('/api/me/permissions'),request('/api/me/menu')]);}
}
async function select(next:string){page.value=next;currentPage.value=0;message('');await run(refresh);}
function options(field:Field):[string,string][]{if(field.choices)return field.choices;const list=field.type==='system'?systems.value:field.type==='menu'?permissions.value.filter(p=>p.type==='MENU'&&(!form.value.systemId||p.systemId===Number(form.value.systemId))&&p.id!==editing.value?.id):departments.value.filter(d=>page.value!=='departments'||d.id!==editing.value?.id);return list.map(r=>[String(r.id),`${r.name}（${r.id}）`]);}
function openEditor(row:Row|null){editing.value=row;form.value=row?{...row}:{};if(!row){if(page.value==='users')form.value.personType='EMPLOYEE';if(page.value==='permissions')form.value.type='MENU';if(page.value==='resources')form.value.method='GET';}if(row&&page.value==='users'&&row.expiresAt){const local=new Date(new Date(row.expiresAt).getTime()-1);form.value.expiresOn=local.toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});}dialog.value?.showModal();}
async function save(){await run(async()=>{const body:Row={};for(const field of editableFields.value){let value=form.value[field.key];if(['department','system','menu'].includes(field.type||''))value=value===''||value==null?null:Number(value);else if(value==null||value==='')value=field.optional?null:'';body[field.key]=value;}await request(`/api/${page.value}${editing.value?'/'+editing.value.id:''}`,editing.value?'PUT':'POST',body);dialog.value?.close();form.value={};await refresh();message('已保存');});}
async function status(row:Row){const field='active' in row?'active':'enabled';if(!confirm(`确认${row[field]?'停用':'启用'}“${row.name||row.displayName}”？此操作会影响所有使用者的有效授权。`))return;await run(async()=>{await request(`/api/${page.value}/${row.id}/status`,'PUT',{[field]:!row[field]});await refresh();message('状态已更新');});}
async function remove(row:Row){if(!confirm(`确认删除“${row.name||row.displayName}”？存在关联引用时将拒绝删除。`))return;await run(async()=>{await request(`/api/${page.value}/${row.id}`,'DELETE');await refresh();message('已删除');});}
async function relation(kind:string,add:boolean){await run(async()=>{const ids=kind==='user'?[userId.value,roleId.value]:kind==='role'?[roleId.value,permissionId.value]:[permissionId.value,resourceId.value];if(ids.some(x=>!x))throw new Error('请先选择关系两端的对象');const route=kind==='user'?`/api/users/${ids[0]}/roles/${ids[1]}`:kind==='role'?`/api/roles/${ids[0]}/permissions/${ids[1]}`:`/api/permissions/${ids[0]}/resources/${ids[1]}`;await request(route,add?'PUT':'DELETE');message(add?'授权关系已建立':'授权关系已解除');await inspect(kind);});}
async function inspect(kind:string){const route=kind==='user'?`/api/users/${userId.value}/roles`:kind==='role'?`/api/roles/${roleId.value}/permissions`:`/api/permissions/${permissionId.value}/resources`;grantRows.value=await request(route);}
function display(key:string,value:any){if(value===null||value===undefined||value==='')return '—';if(['enabled','active'].includes(key))return value?'启用':'停用';if(key==='personType')return personChoices.find(x=>x[0]===value)?.[1]||value;if(key==='type')return value==='MENU'?'菜单':'按钮';if(['departmentId','parentId'].includes(key)&&page.value==='users')return departments.value.find(x=>x.id===value)?.name||value;return value;}
function flatten(nodes:Row[],depth=0):Row[]{return nodes.flatMap(n=>[{...n.permission,granted:n.granted,depth},...flatten(n.children,depth+1)]);}
onMounted(async()=>{if(token.value)await run(initialize);});
</script>

<template>
 <main v-if="!me" class="login-shell"><section class="login-card"><div class="brand">Cdwy · 统一权限管理系统</div><h1>账号登录</h1><p class="muted">登录后管理角色授权，或查看本人可访问的资源。</p><form @submit.prevent="login"><label>登录名<input v-model="username" autocomplete="username" required maxlength="64"></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="notice" role="alert" :class="['notice',failure?'error':'']">{{notice}}</p><button class="primary wide" :disabled="busy">{{busy?'正在登录…':'登录'}}</button></form></section></main>
 <div v-else class="layout"><aside><div class="brand">Cdwy<br><strong>统一权限管理</strong></div><p class="eyebrow">基础管理</p><nav><template v-if="me.administrator"><button v-for="key in adminPages" :key="key" :class="{selected:page===key}" @click="select(key)">{{screens[key]?.title||'授权关系'}}</button></template><button :class="{selected:page==='mine'}" @click="select('mine')">我的权限</button><button :class="{selected:page==='password'}" @click="select('password')">修改密码</button></nav><div class="aside-footer">第一轮检查整改版本</div></aside>
 <div class="workspace"><header><span>{{me.administrator?'管理员工作区':'个人工作区'}}</span><div>{{me.displayName}} <button @click="logout();message('已退出登录')">退出登录</button></div></header><main><div class="page-heading"><div><p class="eyebrow">统一权限管理系统</p><h1>{{screen?.title||({grants:'授权关系',mine:'我的权限',password:'修改密码'} as Record<string,string>)[page]}}</h1><p class="muted">{{screen?.caption||'用户通过角色获得权限，接口独立执行授权校验。'}}</p></div><button v-if="screen" class="primary" :disabled="busy" @click="openEditor(null)">新增{{page==='permissions'?'权限':page==='resources'?'资源':screen.title.replace('管理','')}}</button></div>
 <p v-if="notice" role="status" :class="['notice',failure?'error':'success']">{{notice}}</p>
 <section v-if="screen" class="panel"><div class="table-wrap"><table><thead><tr><th v-for="[key,label] in screen.columns" :key="key">{{label}}</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td v-for="[key] in screen.columns" :key="key"><span :class="['enabled','active'].includes(key)?(row[key]?'tag positive':'tag'):''">{{display(key,row[key])}}</span></td><td class="actions"><button @click="openEditor(row)">编辑</button><button v-if="'enabled' in row||'active' in row" :disabled="busy" @click="status(row)">{{row.enabled??row.active?'停用':'启用'}}</button><button class="danger" :disabled="busy" @click="remove(row)">删除</button></td></tr><tr v-if="!rows.length"><td :colspan="screen.columns.length+1" class="empty">暂无记录，点击右上角新增。</td></tr></tbody></table></div><footer class="pagination"><span>共 {{total}} 条</span><template v-if="page==='users'"><button :disabled="currentPage===0||busy" @click="currentPage--;run(refresh)">上一页</button><span>第 {{currentPage+1}} 页</span><button :disabled="(currentPage+1)*25>=total||busy" @click="currentPage++;run(refresh)">下一页</button></template></footer></section>
 <div v-if="page==='grants'" class="grant-grid"><section class="panel"><h2>1 用户 → 角色</h2><label>用户<select v-model="userId"><option value="">请选择</option><option v-for="u in users" :value="u.id">{{u.displayName}}（{{u.username}} · {{u.id}}）</option></select></label><label>角色<select v-model="roleId"><option value="">请选择</option><option v-for="r in roles" :value="r.id">{{r.name}}（{{r.id}}）</option></select></label><div class="actions"><button class="primary" :disabled="busy" @click="relation('user',true)">分配</button><button :disabled="busy" @click="relation('user',false)">回收</button><button :disabled="!userId||busy" @click="run(()=>inspect('user'))">查看角色</button></div></section><section class="panel"><h2>2 角色 → 前端权限</h2><label>角色<select v-model="roleId"><option value="">请选择</option><option v-for="r in roles" :value="r.id">{{r.name}}（{{r.id}}）</option></select></label><label>菜单或按钮<select v-model="permissionId"><option value="">请选择</option><option v-for="p in permissions" :value="p.id">{{p.name}} · {{p.type}}（{{p.id}}）</option></select></label><div class="actions"><button class="primary" :disabled="busy" @click="relation('role',true)">授予</button><button :disabled="busy" @click="relation('role',false)">回收</button><button :disabled="!roleId||busy" @click="run(()=>inspect('role'))">查看权限</button></div></section><section class="panel"><h2>3 前端权限 → API 资源</h2><label>菜单或按钮<select v-model="permissionId"><option value="">请选择</option><option v-for="p in permissions" :value="p.id">{{p.name}}（{{p.id}}）</option></select></label><label>API 资源<select v-model="resourceId"><option value="">请选择</option><option v-for="r in resources" :value="r.id">{{r.method}} {{r.path}}（{{r.id}}）</option></select></label><div class="actions"><button class="primary" :disabled="busy" @click="relation('api',true)">绑定</button><button :disabled="busy" @click="relation('api',false)">解绑</button><button :disabled="!permissionId||busy" @click="run(()=>inspect('api'))">查看接口</button></div></section><section class="panel results"><h2>关系查询结果</h2><p v-if="!grantRows.length" class="muted">选择对象后点击查看，也可以先建立授权关系。</p><ul v-else><li v-for="r in grantRows" :key="r.id">{{r.name}} <span class="muted">{{r.method||r.code}} {{r.path||''}} · 编号 {{r.id}}</span></li></ul></section></div>
 <div v-if="page==='mine'" class="two-columns"><section class="panel"><h2>我的菜单与按钮</h2><p class="muted">未直接授权的祖先菜单只作为导航容器。</p><p v-if="!myMenu.length" class="empty">暂无有效权限，请联系管理员分配角色。</p><ul class="permission-tree"><li v-for="p in flatten(myMenu)" :key="p.id" :style="{paddingLeft:(p.depth*24)+'px'}"><span class="tag">{{p.type==='MENU'?'菜单':'按钮'}}</span> {{p.name}} <span class="muted">{{p.granted?'已授权':'导航容器'}}</span></li></ul><p class="muted">有效授权 {{myPermissions.length}} 项</p><button :disabled="busy" @click="run(refresh)">重新读取权限</button></section><section class="panel"><h2>课程接口鉴权示例</h2><p class="muted">用于验证前端权限与 API 资源绑定；这里展示示例课程数据。</p><button class="primary" :disabled="busy" @click="run(async()=>{demo=await request('/api/demo/courses');message('接口鉴权通过')})">调用课程列表接口</button><ul><li v-for="course in demo" :key="course.id">{{course.name}}</li></ul></section></div>
 <section v-if="page==='password'" class="panel password-panel"><h2>修改本人密码</h2><form @submit.prevent="run(async()=>{await request('/api/me/password','PUT',{currentPassword,newPassword});currentPassword='';newPassword='';logout();message('密码已修改，请重新登录')})"><label>原密码<input v-model="currentPassword" type="password" autocomplete="current-password" required></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="8"><small>至少 8 个字符，大小写、数字、符号中至少三类。</small></label><button class="primary" :disabled="busy">确认修改</button></form></section>
 </main></div>
 <dialog ref="dialog" aria-labelledby="editor-title" @close="form={}"><form @submit.prevent="save"><h2 id="editor-title">{{editing?'编辑':'新增'}}{{screen?.title}}</h2><p class="muted">启用与停用请在列表中单独操作。</p><label v-for="field in editableFields" :key="field.key">{{field.label}}<select v-if="field.choices||['department','system','menu'].includes(field.type||'')" v-model="form[field.key]" :required="!field.optional"><option value="">{{field.optional?'无／不设置':'请选择'}}</option><option v-for="[value,label] in options(field)" :key="value" :value="value">{{label}}</option></select><input v-else v-model="form[field.key]" :type="field.type||'text'" :required="!field.optional" :maxlength="field.type==='password'?72:255" :autocomplete="field.type==='password'?'new-password':'off'"><small v-if="field.key==='expiresOn'">外部或临时人员必填，期限上限由管理员配置。</small></label><p v-if="notice&&failure" class="notice error" role="alert">{{notice}}</p><div class="actions"><button class="primary" :disabled="busy">保存</button><button type="button" :disabled="busy" @click="dialog?.close()">取消</button></div></form></dialog>
 </div>
</template>
